items.solution:
function isValid(premiseFn, conclusionFn) {
  for (const P of [false, true]) {
    for (const Q of [false, true]) {
      const env = { P, Q };
      if (premiseFn(env) && !conclusionFn(env)) {
        return { valid: false, counterexample: env };
      }
    }
  }
  return { valid: true };
}
